import { GoogleGenAI, Type } from "@google/genai";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

export const extractDataFromLicense = async (
  front: File,
  back: File,
  reference?: File | null
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    try {
      const refBase64 = await fileToBase64(reference);
      parts.push({ 
        inlineData: { 
          data: refBase64, 
          mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document" 
        } 
      });
      referenceInstruction = `
        CONTEXTO DE REFERENCIA: He incluido un documento Word que sirve como ejemplo. 
        Analiza cómo se extrajeron los datos en ese documento y aplica la misma lógica 
        para estas nuevas imágenes de licencia.
      `;
    } catch (e) {
      console.warn("No se pudo procesar el archivo de referencia, procediendo sin él.");
    }
  }

  const prompt = `
    Analyze these two images of a driver's license (Front and Back).
    ${referenceInstruction}

    Standard numerical codes found on licenses:
    1: Surname/Last Name
    2: First Name(s)
    3: Date of Birth
    4a: Issue Date
    4b: Expiry Date
    4d: License/ID Number
    8: Address
    9: Category/Class

    Instructions:
    1. Identify fields using these numbers first.
    2. Use the provided reference document structure if available.
    3. Translate extracted values to English.
    4. If a field is not found, return an empty string "".
    5. Return valid JSON.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            expiryDate: { type: Type.STRING },
            address: { type: Type.STRING },
            nationality: { type: Type.STRING },
            gender: { type: Type.STRING },
            class: { type: Type.STRING },
          },
          // Eliminamos 'required' para que no falle si la IA tiene dudas
          required: []
        }
      }
    });

    const jsonStr = response.text.trim();
    return JSON.parse(jsonStr) as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "La IA no pudo procesar las imágenes. Intenta con fotos más claras.");
  }
};

