import { GoogleGenAI, Type } from "@google/genai";
import PizZip from "pizzip";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

/**
 * Extrae texto de un archivo .docx usando PizZip
 */
const extractTextFromDocx = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new PizZip(arrayBuffer);
    const docXml = zip.file("word/document.xml")?.asText();
    if (!docXml) return "";

    // Limpieza básica de XML para reducir tokens, aunque Gemini entiende XML bien
    return docXml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    console.error("Error leyendo Word de referencia:", e);
    return "";
  }
};

export const extractDataFromLicense = async (
  front: File,
  back: File,
  reference?: File | null
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `
        CONTEXTO DE REFERENCIA (Extraído de un documento Word previo):
        "${referenceText}"

        Usa el texto anterior para entender cómo se deben mapear los campos de la nueva licencia.
      `;
    }
  }

  const prompt = `
    Analyze these two images of a driver's license (Front and Back).
    ${referenceInstruction}

    Standard numerical codes found on licenses:
    1: Surname/Last Name
    2: First Name(s)
    3: Date of Birth
    4a: Issue Date
    4b: Expiry Date
    4d: License/ID Number
    8: Address
    9: Category/Class

    Instructions:
    1. Identify fields using these numbers first.
    2. Use the provided reference text to guide the mapping if available.
    3. Translate extracted values to English.
    4. If a field is not found, return an empty string "".
    5. Return valid JSON.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            fullName: { type: Type.STRING },
