import { GoogleGenAI, Type } from "@google/genai";
import PizZip from "pizzip";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

const extractTextFromDocx = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new PizZip(arrayBuffer);
    const docXml = zip.file("word/document.xml")?.asText();
    if (!docXml) return "";
    return docXml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    console.error("Error leyendo Word de referencia:", e);
    return "";
  }
};

export const extractDataFromLicense = async (
  front: File,
  back: File,
  reference?: File | null
): Promise<ExtractedData> => {
  const frontBase64 = await fileToBase64(front);
  const backBase64 = await fileToBase64(back);

  const parts: any[] = [
    { inlineData: { data: frontBase64, mimeType: front.type } },
    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `REFERENCE CONTEXT: "${referenceText}"`;
    }
  }

  const prompt = `
    Analyze these two images (Front and Back of a license).
    ${referenceInstruction}

    TASK 1: Extract all text data following professional rules.
    TASK 2: Analyze image orientation and position.

    IMAGE PROCESSING RULES:
    1. For each image, detect the "license card" itself.
    2. Provide a bounding box [ymin, xmin, ymax, xmax] in normalized coordinates (0-1000) that tightly contains the card.
    3. Detect if the image is rotated. Provide "frontRotation" and "backRotation" as 0, 90, 180, or 270 (degrees clockwise) needed to make the text horizontal and readable.

    TEXT RULES:
    - Format dates as "DD Month YYYY" in English.
    - Translate everything to English.
    - Authority must include ", France".

    Return valid JSON.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            surname: { type: Type.STRING },
            firstNames: { type: Type.STRING },
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            placeOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            expiryDate: { type: Type.STRING },
            address: { type: Type.STRING },
            nationality: { type: Type.STRING },
            gender: { type: Type.STRING },
            class: { type: Type.STRING },
            codes: { type: Type.STRING },
            authority: { type: Type.STRING },
            categoriesDates: { type: Type.STRING },
            // Coordenadas de recorte
            frontRotation: { type: Type.NUMBER },
            backRotation: { type: Type.NUMBER },
            frontBox: { type: Type.ARRAY, items: { type: Type.NUMBER } },
            backBox: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          }
        }
      }
    });

    return JSON.parse(response.text.trim()) as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "La IA no pudo procesar las imágenes.");
  }
};

import PizZip from "pizzip";
import Docxtemplater from "docxtemplater";
// @ts-ignore
import ImageModule from "docxtemplater-image-module-free";
import { ExtractedData } from "../types";

const formatProfessionalDate = (date: Date): string => {
  const day = String(date.getDate()).padStart(2, '0');
  const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  return `${day} ${months[date.getMonth()]} ${date.getFullYear()}`;
};

/**
 * Procesa la imagen: aplica rotación y recorta según el Bounding Box de la IA.
 */
export const processLicenseImage = async (
  file: File, 
  box?: number[], 
  rotation: number = 0
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) return reject(new Error("No canvas context"));

        // 1. Manejar Rotación
        // Si rotamos 90 o 270, invertimos dimensiones
        const isVertical = rotation === 90 || rotation === 270;
        const origW = img.width;
        const origH = img.height;

        canvas.width = isVertical ? origH : origW;
        canvas.height = isVertical ? origW : origH;

        ctx.save();
        ctx.translate(canvas.width / 2, canvas.height / 2);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -origW / 2, -origH / 2);
        ctx.restore();

        // 2. Manejar Recorte si existe Box [ymin, xmin, ymax, xmax]
        if (box && box.length === 4) {
          const [ymin, xmin, ymax, xmax] = box;
          // El box es sobre la imagen ORIGINAL antes de rotar en la mente de Gemini
          // pero Gemini suele darlo sobre la vista que tiene. 
          // Para simplificar, recortamos sobre el resultado rotado o asumimos el crop relativo
          const cropX = (xmin / 1000) * canvas.width;
          const cropY = (ymin / 1000) * canvas.height;
          const cropW = ((xmax - xmin) / 1000) * canvas.width;
          const cropH = ((ymax - ymin) / 1000) * canvas.height;

          const cropCanvas = document.createElement('canvas');
          cropCanvas.width = cropW;
          cropCanvas.height = cropH;
          const cropCtx = cropCanvas.getContext('2d');
          cropCtx?.drawImage(canvas, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);

          resolve(cropCanvas.toDataURL('image/jpeg', 0.85));
        } else {
          resolve(canvas.toDataURL('image/jpeg', 0.85));
        }
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

export const optimizeImage = async (file: File): Promise<string> => {
  return processLicenseImage(file); // Por defecto solo optimiza
};

export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  frontImgBase64: string,
  backImgBase64: string
): Promise<Blob> => {
  try {
    const arrayBuffer = await template.arrayBuffer();
    const zip = new PizZip(new Uint8Array(arrayBuffer));

    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        const base64 = tagValue.includes(',') ? tagValue.split(',')[1] : tagValue;
        const binaryString = window.atob(base64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
        return bytes.buffer;
      },
      getSize: () => [312, 195], // 30% más grande que el original de 240x150
    };

    const ImageModuleClass = ImageModule.default || ImageModule;
    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [new ImageModuleClass(imageOptions)],
      delimiters: { start: '{{', end: '}}' },
      nullGetter() { return ""; }
    });

    const val = (v: any) => (v === undefined || v === null || v === "N/A" || v === "null" ? "" : String(v));

    const fullData = {
      ...data,
      surname: val(data.surname),
      firstNames: val(data.firstNames),
      fullName: val(data.fullName || `${data.surname} ${data.firstNames}`),
      foto_frente: frontImgBase64,
      foto_reverso: backImgBase64,
      license_front: frontImgBase64,
      license_back: backImgBase64,
      today: formatProfessionalDate(new Date()),
      fechaHoy: formatProfessionalDate(new Date()),
    };

    doc.render(fullData);
    return doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });
  } catch (error: any) {
    throw new Error(error.message || "Error al generar el archivo Word.");
  }
};

