    { inlineData: { data: backBase64, mimeType: back.type } }
  ];

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `REFERENCE CONTEXT FROM PREVIOUS DOCUMENT: "${referenceText}"`;
    }
  }

  const prompt = `
    Analyze these two images (Front and Back of a driver's license).
    ${referenceInstruction}

    EXTRACT DATA RULES:
    1. "surname": Family name (Apellidos).
    2. "firstNames": Given names (Nombres).
    3. "licenseNumber": The main identification number of the license.
    4. "dateOfBirth": Point 3 date.
    5. "placeOfBirth": Point 3 location.
    6. "issueDate": Point 4a.
    7. "expiryDate": Point 4b.
    8. "authority": Extract value from Point 4c and ALWAYS append the country name at the end. Example: "Prefect 22, France".
    9. "class": Extract ALL categories listed in Point 9 on the FRONT. SEPARATE THEM WITH COMMAS AND SPACES (e.g., "A, B, CE"). DO NOT use slashes.
    10. "categoriesDates": Analyze the BACK table, Column 10. Group identical dates (e.g., "A1, B: 12 May 2015").
    11. "codes": Look ONLY at the TOP LEFT corner of the BACK. Extract the series of 3 strings (usually 2 horizontal and 1 vertical). DO NOT include anything else. DO NOT include codes from Column 12 or any other section. Stop exactly after these 3 identification strings.
    12. SPECIAL CODE 106: If you find the code "106" (often on the back):
        - Look for two dates associated with it (usually formatted as DD.MM.YY or similar).
        - "code106From": The start date of this restriction.
        - "code106To": The end date of this restriction.
    13. Format all dates as "DD Month YYYY".

    Return valid JSON matching the schema.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            surname: { type: Type.STRING },
            firstNames: { type: Type.STRING },
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            placeOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            expiryDate: { type: Type.STRING },
            class: { type: Type.STRING },
            codes: { type: Type.STRING },
            authority: { type: Type.STRING },
            categoriesDates: { type: Type.STRING },
            code106From: { type: Type.STRING, description: "Start date for code 106 if present" },
            code106To: { type: Type.STRING, description: "End date for code 106 if present" },
          }
        }
      }
    });

    const result = JSON.parse(response.text.trim());
    if (!result.fullName) {
      result.fullName = `${result.surname || ''} ${result.firstNames || ''}`.trim();
    }
    return result as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "La IA no pudo procesar las imágenes.");
  }
};

