import { GoogleGenAI, Type } from "@google/genai";
import PizZip from "pizzip";
import { ExtractedData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64String = (reader.result as string).split(',')[1];
      resolve(base64String);
    };
    reader.onerror = error => reject(error);
  });
};

const extractTextFromDocx = async (file: File): Promise<string> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const zip = new PizZip(arrayBuffer);
    const docXml = zip.file("word/document.xml")?.asText();
    if (!docXml) return "";
    return docXml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    console.error("Error reading reference Word:", e);
    return "";
  }
};

export const extractDataFromLicense = async (
  images: File[],
  reference?: File | null
): Promise<ExtractedData> => {
  const parts: any[] = [];

  for (const img of images) {
    const b64 = await fileToBase64(img);
    parts.push({ inlineData: { data: b64, mimeType: img.type } });
  }

  let referenceInstruction = "";
  if (reference) {
    const referenceText = await extractTextFromDocx(reference);
    if (referenceText) {
      referenceInstruction = `REFERENCE CONTEXT FROM PREVIOUS DOCUMENT: "${referenceText}"`;
    }
  }

  const prompt = `
    Analyze these 4 images of a Chinese Driver's License (usually includes Main License Front/Back and Secondary Record Front/Back).
    ${referenceInstruction}

    IMPORTANT: TRANSLATE ALL CHINESE TEXT TO ENGLISH.

    EXTRACTION RULES FOR CHINESE LICENSES:
    1. "surname": Identify the family name (usually the first character of the full name in Chinese).
    2. "firstName": The rest of the characters in the name.
    3. "fullName": The full name in Pinyin if available, otherwise translate the Chinese characters to English/Pinyin.
    4. "licenseNumber": The ID number (usually matches the Citizen ID).
    5. "gender": Translate M/F.
    6. "nationality": Translate to English (e.g., "Chinese").
    7. "address": Full address translated to English.
    8. "dateOfBirth": Format as "DD Month YYYY".
    9. "issueDate": First issue date.
    10. "class": Vehicle class (e.g., C1, C2).
    11. "validFrom" & "validTo": The validity period.
    12. "authority": The issuing department (Seal/Stamp text), translated to English.
    13. "secondaryRecords": Extract text from the "Secondary Record" sheet (remarks, audit dates, or file numbers).

    If any data is missing from the images, return an empty string for that field.
    Return valid JSON.
  `;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            surname: { type: Type.STRING },
            firstName: { type: Type.STRING },
            fullName: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            gender: { type: Type.STRING },
            nationality: { type: Type.STRING },
            address: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING },
            issueDate: { type: Type.STRING },
            validFrom: { type: Type.STRING },
            validTo: { type: Type.STRING },
            class: { type: Type.STRING },
            authority: { type: Type.STRING },
            secondaryRecords: { type: Type.STRING },
          }
        }
      }
    });

    const result = JSON.parse(response.text.trim());
    return result as ExtractedData;
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(error.message || "The AI could not process the Chinese license images.");
  }
};

