const formatProfessionalDate = (date: Date): string => {
  const day = String(date.getDate()).padStart(2, '0');
  const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  return `${day} ${months[date.getMonth()]} ${date.getFullYear()}`;
};

export const optimizeImage = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        // Redimensionamos a un tamaño estándar para licencias para evitar archivos Word pesados
        const maxWidth = 800;
        const scale = img.width > maxWidth ? maxWidth / img.width : 1;
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        if (ctx) {
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        }
        // Retornamos el base64 sin el prefijo data:image... para procesarlo más fácil
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        resolve(dataUrl);
      };
      img.onerror = () => reject(new Error("Error al cargar la imagen."));
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
};

export const generateFilledDoc = async (
  template: File,
  data: ExtractedData,
  images: string[] 
): Promise<Blob> => {
  try {
    const arrayBuffer = await template.arrayBuffer();
    const zip = new PizZip(new Uint8Array(arrayBuffer));

    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        // tagValue es el string base64
        const base64 = tagValue.includes(',') ? tagValue.split(',')[1] : tagValue;
        const binaryString = window.atob(base64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
        return bytes.buffer;
      },
      getSize: () => [312, 195], // Tamaño aproximado de una tarjeta de licencia en puntos
    };

    const ImageModuleClass = ImageModule.default || ImageModule;

    // Configuramos los delimitadores y añadimos el módulo de imagen
    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [new ImageModuleClass(imageOptions)],
      nullGetter() { return ""; }
    });

    const val = (v: any) => (v === undefined || v === null || v === "N/A" || v === "null" ? "" : String(v));

    const fullData = {
      ...data,
      assignedNumber: val(data.assignedNumber),
      surname: val(data.surname),
      firstName: val(data.firstName),
      fullName: val(data.fullName),
      class: val(data.class),
      licenseNumber: val(data.licenseNumber),
      authority: val(data.authority),
      firstIssued: val(data.firstIssued),
      issueDate: val(data.issueDate),
      expiryDate: val(data.expiryDate),
      explicacionCodigos: val(data.explicacionCodigos),
      barcodeNumber: val(data.barcodeNumber),
      fileNumber: val(data.fileNumber),
      validPeriod: `${val(data.issueDate)} - ${val(data.expiryDate)}`,
      // En el objeto de datos, las llaves de las fotos NO llevan el % ni las llaves
      foto_1: images[0],
      foto_2: images[1],
      foto_3: images[2],
      foto_4: images[3],
      today: formatProfessionalDate(new Date()),
      fechaHoy: formatProfessionalDate(new Date()),
    };

    doc.render(fullData);

    return doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });
  } catch (error: any) {
    console.error("Error en renderizado:", error);
    throw new Error(error.message || "Error al generar el archivo Word.");
  }
};

