    const zip = new PizZip(new Uint8Array(arrayBuffer));

    const imageOptions = {
      centered: false,
      getImage: (tagValue: string) => {
        try {
          if (!tagValue) return new ArrayBuffer(0);
          const base64 = tagValue.includes(',') ? tagValue.split(',')[1] : tagValue;
          const binaryString = window.atob(base64);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
          return bytes.buffer;
        } catch (e) {
          console.error("Error decoding image base64:", e);
          return new ArrayBuffer(0);
        }
      },
      getSize: () => [312, 195], 
    };

    // Robust instantiation for ESM imports
    const ImageModuleClass = ImageModule.default || ImageModule;
    const DocxtemplaterClass = (Docxtemplater as any).default || Docxtemplater;

    if (!DocxtemplaterClass) {
      throw new Error("Docxtemplater library not loaded correctly.");
    }

    const imageModule = new ImageModuleClass(imageOptions);

    const doc = new DocxtemplaterClass(zip, {
      paragraphLoop: true,
      linebreaks: true,
      modules: [imageModule],
      nullGetter() { return ""; }
    });

    const val = (v: any) => (v === undefined || v === null || v === "N/A" || v === "null" ? "" : String(v));

    const fullData = {
      ...data,
      assignedNumber: val(data.assignedNumber),
      surname: val(data.surname),
      firstName: val(data.firstName),
      fullName: val(data.fullName),
      class: val(data.class),
      licenseNumber: val(data.licenseNumber),
      authority: val(data.authority),
      firstIssued: val(data.firstIssued),
      issueDate: val(data.issueDate),
      expiryDate: val(data.expiryDate),
      explicacionCodigos: val(data.explicacionCodigos),
      barcodeNumber: val(data.barcodeNumber),
      fileNumber: val(data.fileNumber),
      validPeriod: `${val(data.issueDate)} - ${val(data.expiryDate)}`,
      foto_1: images[0] || "",
      foto_2: images[1] || "",
      foto_3: images[2] || "",
      foto_4: images[3] || "",
      today: formatProfessionalDate(new Date()),
      fechaHoy: formatProfessionalDate(new Date()),
    };

    doc.setData(fullData);
    doc.render();

    const output = doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });

    return output;
  } catch (error: any) {
    console.error("Docxtemplater error context:", error);
    if (error.properties && error.properties.errors instanceof Array) {
      const errorMessages = error.properties.errors.map((e: any) => e.message).join("\n");
      throw new Error("Template processing failed: " + errorMessages);
    }
    throw new Error(error.message || "Error generating Word file.");
  }
};

