      "%foto_2": images[1] || "",
      "%foto_3": images[2] || "",
      "%foto_4": images[3] || "",
      today: formatProfessionalDate(new Date()),
      fechaHoy: formatProfessionalDate(new Date()),
    };

    doc.render(renderData);

    return doc.getZip().generate({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      compression: "DEFLATE",
    });
  } catch (error: any) {
    console.error("Error detallado de Docxtemplater:", error);

    // Si es un error de tags duplicados o mal cerrados, intentamos dar más info
    if (error.properties && error.properties.errors) {
      const specificErrors = error.properties.errors
        .map((e: any) => `${e.message} en el tag: "${e.properties?.explanation || 'desconocido'}"`)
        .join("\n");
      throw new Error("Error en la plantilla Word:\n" + specificErrors);
    }

    throw new Error(error.message || "Error al generar el Word.");
  }
};

